from solution import is_simple_power
import pytest
from hypothesis import given, HealthCheck
import hypothesis.strategies as st


def reference(x, n):
    # Obviously correct brute force: exists k >= 0 with n**k == x
    # Python ** semantics (so 0**0 == 1).
    for k in range(0, 500):
        try:
            p = pow(n, k)
        except Exception:
            continue
        if p == x:
            return True
        # abs grows monotonically for |n| >= 2, so we can stop
        if abs(n) >= 2 and abs(x) > 1 and abs(p) > abs(x):
            break
    return False


# ---- concrete examples from the spec ----
@pytest.mark.parametrize(
    "x,n,expected",
    [
        (1, 4, True),
        (2, 2, True),
        (8, 2, True),
        (3, 2, False),
        (3, 1, False),
        (5, 3, False),
    ],
)
def test_spec_examples(x, n, expected):
    assert is_simple_power(x, n) is expected


def test_one_is_always_simple_power():
    # n**0 == 1 for every int n (Python semantics), so x==1 is always True
    for n in [-10, -2, -1, 0, 1, 2, 3, 4, 10, 100]:
        assert is_simple_power(1, n) is True


def test_base_one_only_one_is_power():
    # 1**k == 1 for all k, so only x==1 is True
    assert is_simple_power(1, 1) is True
    for x in [0, 2, 3, 5, 8, 9, 100, -1]:
        assert is_simple_power(x, 1) is False


def test_zero_x_nonzero_base_is_false():
    # for n != 0, n**k != 0 for every k >= 0
    for n in [2, 3, 4, 10, -2]:
        assert is_simple_power(0, n) is False


def test_zero_base_does_not_raise():
    # n==0 is valid input (int,int); must return bool, not raise
    r0 = is_simple_power(0, 0)
    r1 = is_simple_power(1, 0)
    r2 = is_simple_power(2, 0)
    assert r0 is True  # 0**1 == 0
    assert r1 is True  # 0**0 == 1
    assert r2 is False


def test_large_exact_power_is_true():
    # 3**40 needs exact integer arithmetic; float division loses precision
    assert is_simple_power(3**40, 3) is True
    assert is_simple_power(2**60, 2) is True
    assert is_simple_power(10**18, 10) is True


def test_negative_base_powers():
    assert is_simple_power(-8, -2) is True  # (-2)**3
    assert is_simple_power(4, -2) is True  # (-2)**2
    assert is_simple_power(-2, -2) is True  # (-2)**1
    assert is_simple_power(1, -2) is True  # (-2)**0
    assert is_simple_power(-1, -2) is False
    assert is_simple_power(8, -2) is False
    assert is_simple_power(-8, 2) is False


@given(
    x=st.integers(min_value=-200, max_value=2000),
    n=st.integers(min_value=-5, max_value=5),
)
def test_equivalence_to_reference_model(x, n):
    assert is_simple_power(x, n) is reference(x, n)


@given(
    n=st.integers(min_value=-10, max_value=10),
    k=st.integers(min_value=0, max_value=12),
)
def test_constructed_true_powers(n, k):
    # by definition n**k is a simple power of n
    try:
        x = pow(n, k)
    except Exception:
        return
    # keep size bounded so test stays fast
    if abs(x) > 10**6:
        return
    assert is_simple_power(x, n) is True


@given(
    x=st.integers(min_value=0, max_value=500),
    n=st.integers(min_value=2, max_value=10),
)
def test_non_powers_are_false(x, n):
    # cross-check negative property against reference
    if reference(x, n):
        assert is_simple_power(x, n) is True
    else:
        assert is_simple_power(x, n) is False
